5	/**
6	 * Derives an owner's {@code locality} from its city using a fixed city-to-region
7	 * table. Kept out of the mapper interface deliberately: MapStruct treats any
8	 * single-argument method on a {@code @Mapper} interface as a candidate mapping
9	 * method, so a {@code String -> String} helper there would be applied to every
10	 * String property. This static lookup is referenced only from an explicit
11	 * mapping expression instead.
12	 */
13	public final class LocalityLookup {
14	
15	    /** City -> canonical region; an exact, case-sensitive mapping. */
16	    private static final Map<String, String> CITY_REGION = Map.of(
17	        "Sydney", "NSW",
18	        "Melbourne", "VIC",
19	        "Brisbane", "QLD");
20	
21	    private LocalityLookup() {
22	    }
23	
24	    /**
25	     * Returns the canonical region for {@code city} from the fixed table, or
26	     * {@code 'UNKNOWN'} when the city is not in the table.
27	     *
28	     * @param city the owner's city, possibly {@code null}
29	     * @return the canonical region, or {@code 'UNKNOWN'} if the city is unknown
30	     */
31	    public static String regionFor(String city) {
32	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
33	    }
