66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Dedicated audit logger. On successful owner create an audit line is emitted here carrying
73	     * the newly assigned owner id, customer code, registration date and membership level.
74	     */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    private final ClinicService clinicService;
78	
79	    private final OwnerMapper ownerMapper;
80	
81	    private final PetMapper petMapper;
82	
83	    private final VisitMapper visitMapper;
