85	    public OwnerRestControllerV1(ClinicService clinicService,
86	                                 OwnerMapper ownerMapper,
87	                                 PetMapper petMapper,
88	                                 VisitMapper visitMapper) {
89	        this.clinicService = clinicService;
90	        this.ownerMapper = ownerMapper;
91	        this.petMapper = petMapper;
92	        this.visitMapper = visitMapper;
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
98	        Collection<Owner> owners;
99	        if (lastName != null) {
100	            owners = this.clinicService.findOwnerByLastName(lastName);
101	        } else {
102	            owners = this.clinicService.findAllOwners();
103	        }
104	        if (owners.isEmpty()) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
113	        Owner owner = this.clinicService.findOwnerById(ownerId);
114	        if (owner == null) {
115	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
116	        }
117	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        normalizeAddress(ownerFieldsDto);
124	        validateRequiredFields(ownerFieldsDto);
125	        normalizeTelephone(ownerFieldsDto);
126	        normalizeEmail(ownerFieldsDto);
127	        rejectDuplicateIdentity(ownerFieldsDto);
128	        rejectCityAtCapacity(ownerFieldsDto.getCity());
129	        defaultRegistrationDate(ownerFieldsDto);
130	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
131	        HttpHeaders headers = new HttpHeaders();
132	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
133	        assignCustomerCode(owner);
134	        assignHouseholdId(owner);
135	        assignHouseholdMemberCount(owner);
136	        assignNamesakeCount(owner);
137	        assignMembershipNumber(owner);
138	        assignBulkSignupWarning(owner);
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
141	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        normalizeEmail(ownerFieldsDto);
156	        currentOwner.setAddress(ownerFieldsDto.getAddress());
157	        currentOwner.setCity(ownerFieldsDto.getCity());
158	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
159	        currentOwner.setLastName(ownerFieldsDto.getLastName());
160	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
161	        currentOwner.setEmail(ownerFieldsDto.getEmail());
162	        this.clinicService.saveOwner(currentOwner);
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
170	        Owner owner = this.clinicService.findOwnerById(ownerId);
171	        if (owner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        this.clinicService.deleteOwner(owner);
175	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	    }
