230	    /**
231	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
232	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
233	     * Validation already rejects {@code null} values and the pattern-constrained fields
234	     * when blank, but {@code address} and {@code city} have no pattern, so a
235	     * whitespace-only value would otherwise slip through.
236	     *
237	     * @param ownerFieldsDto the submitted owner fields
238	     * @throws RequiredFieldsMissingException if any required field is missing or blank
239	     */
240	    /**
241	     * Common street-type abbreviations expanded during address normalization. Keys are the
242	     * upper-cased abbreviation tokens; values are their canonical expansions.
243	     */
244	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
245	        "ST", "STREET",
246	        "RD", "ROAD",
247	        "AVE", "AVENUE");
248	
249	    /**
250	     * Normalizes the submitted address on create and writes the canonical value back onto the
251	     * request so it is persisted, echoed back, and used for every downstream address comparison
252	     * (household duplicate detection and the household id). The value is trimmed, internal
253	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
254	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
255	     * {@code null} address is left untouched so the required-field check can report it as missing.
256	     *
257	     * @param ownerFieldsDto the submitted owner fields
258	     */
259	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
260	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
261	    }
262	
263	    /**
264	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
265	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
266	     * expanded to its full form. A {@code null} value is returned unchanged.
267	     *
268	     * @param raw the address to canonicalize, possibly {@code null}
269	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
270	     */
271	    private static String normalizeAddress(String raw) {
272	        if (raw == null) {
273	            return null;
274	        }
275	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
276	        if (collapsed.isEmpty()) {
277	            return collapsed;
278	        }
279	        String[] tokens = collapsed.split(" ");
280	        StringBuilder sb = new StringBuilder(collapsed.length());
281	        for (int i = 0; i < tokens.length; i++) {
282	            if (i > 0) {
283	                sb.append(' ');
284	            }
285	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
286	        }
287	        return sb.toString();
288	    }
