325	    /**
326	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
327	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
328	     * and country code are present they are kept; otherwise country code {@code '+61'} is
329	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
330	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
331	     * the national-number length must match the country: {@code '+61'} (Australia) requires
332	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
333	     *
334	     * @param raw the submitted telephone, possibly {@code null}
335	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
336	     */
337	    private static String toE164(String raw) {
338	        if (raw == null) {
339	            return null;
340	        }
341	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
342	        String digits;
343	        if (cleaned.startsWith("+")) {
344	            digits = cleaned.substring(1);
345	        } else {
346	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
347	            digits = "61" + national;
348	        }
349	        if (!digits.matches("[0-9]{8,15}")) {
350	            return null;
351	        }
352	        if (digits.startsWith("61")) {
353	            // Australia: exactly 9 national digits after the '+61' country code.
354	            if (digits.length() - 2 != 9) {
355	                return null;
356	            }
357	        } else if (digits.startsWith("1")) {
358	            // NANP: exactly 10 national digits after the '+1' country code.
359	            if (digits.length() - 1 != 10) {
360	                return null;
361	            }
362	        }
363	        return "+" + digits;
364	    }
365	
366	    /**
367	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
368	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
369	     * each stored owner's telephone is normalized the same way before comparison so differing
370	     * input formats collapse to the same value.
371	     *
372	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
373	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
374	     *                                     same E.164 telephone
375	     */
376	    /**
377	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
378	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
379	     * the parts may contain whitespace or a second {@code @}.
380	     */
381	    private static final Pattern EMAIL_PATTERN =
382	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
383	
384	    /**
385	     * Normalizes the submitted email when present: the value is trimmed, required to be a
386	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
387	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
388	     *
389	     * @param ownerFieldsDto the submitted owner fields
390	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
391	     */
392	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
393	        String email = ownerFieldsDto.getEmail();
394	        if (email == null) {
395	            return;
396	        }
397	        String trimmed = email.strip();
398	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
399	            throw new InvalidEmailException(email);
400	        }
401	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
402	    }
