404	    /**
405	     * Establishes the effective registration date on create and rolls it onto a business day.
406	     * When the client does not supply a {@code registrationDate} it defaults to the server's
407	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
408	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
409	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
410	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
411	     * the membership number's year segment and the daily create-limit).
412	     *
413	     * @param ownerFieldsDto the submitted owner fields
414	     */
415	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
416	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
417	        if (effective == null) {
418	            effective = LocalDate.now();
419	        }
420	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
421	    }
422	
423	    /**
424	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
425	     * following Monday; any weekday is returned unchanged.
426	     *
427	     * @param date the date to adjust
428	     * @return the same date when it is a weekday, otherwise the next Monday
429	     */
430	    private static LocalDate toBusinessDay(LocalDate date) {
431	        return switch (date.getDayOfWeek()) {
432	            case SATURDAY -> date.plusDays(2);
433	            case SUNDAY -> date.plusDays(1);
434	            default -> date;
435	        };
436	    }
