438	    /**
439	     * Assigns the owner's {@code customerCode} on create, formatted
440	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where CITY3 is the upper-cased first three letters of
441	     * {@code city}, LAST3 the upper-cased first three letters of {@code lastName}, and NNNN a
442	     * per-city 4-digit zero-padded sequence equal to one more than the number of owners already
443	     * in that city (compared case-insensitively) — e.g. {@code 'SYD-SMI-0007'}.
444	     *
445	     * @param owner the owner being created (with its {@code city} and {@code lastName} already set)
446	     */
447	    private void assignCustomerCode(Owner owner) {
448	        String city = owner.getCity();
449	        String lastName = owner.getLastName();
450	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
451	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
452	        long sequence = this.clinicService.findAllOwners().stream()
453	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
454	            .count() + 1;
455	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
456	    }
457	
458	    /**
459	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
460	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
461	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
462	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
463	     * canonicalized fields, every owner in the same household — including one joining an existing
464	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
465	     * order.
466	     *
467	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
468	     */
469	    private void assignHouseholdId(Owner owner) {
470	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getAddress()));
471	    }
472	
473	    /**
474	     * Derives the stable {@code householdId} for the given {@code lastName} and {@code address}:
475	     * {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the SHA-256
476	     * digest of the collapsed {@code lastName} and {@code address} (see {@link #collapse}) joined
477	     * by a {@code '\n'}. Because it is derived purely from those two canonicalized fields, every
478	     * owner in the same household receives the same value, independent of create order. Shared by
479	     * {@link #assignHouseholdId} (which persists it) and {@link #identityKeyFor} (which folds it
480	     * into the identity key for duplicate detection).
481	     *
482	     * @param lastName the owner's last name
483	     * @param address  the owner's address
484	     * @return the derived household id
485	     */
486	    private static String householdIdFor(String lastName, String address) {
487	        String key = collapse(lastName) + "\n" + collapse(address);
488	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
489	    }
490	
491	    /**
492	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
493	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
494	     * after this create. Because {@code householdId} is derived from the owner's collapsed
495	     * {@code lastName} and {@code address} (see {@link #assignHouseholdId}), the count reflects every
496	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
497	     * The count is taken before this owner is persisted, so it is one more than the number of
498	     * existing household members.
499	     *
500	     * @param owner the owner being created (with its {@code householdId} already assigned)
501	     */
502	    private void assignHouseholdMemberCount(Owner owner) {
503	        String householdId = owner.getHouseholdId();
504	        long existing = this.clinicService.findAllOwners().stream()
505	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
506	            .count();
507	        owner.setHouseholdMemberCount((int) (existing + 1));
508	    }
509	
510	    /**
511	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
512	     * already share this owner's {@code firstName} and {@code lastName}, compared
513	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
514	     * pre-existing namesakes.
515	     *
516	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
517	     */
518	    private void assignNamesakeCount(Owner owner) {
519	        String firstName = owner.getFirstName();
520	        String lastName = owner.getLastName();
521	        long count = this.clinicService.findAllOwners().stream()
522	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
523	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
524	            .count();
525	        owner.setNamesakeCount((int) count);
526	    }
527	
528	    /**
529	     * Assigns the owner's {@code membershipNumber} on create, formatted
530	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
531	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
532	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
533	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
534	     *
535	     * @param owner the owner being created (with its {@code customerCode} and
536	     *              {@code registrationDate} already set)
537	     */
538	    private void assignMembershipNumber(Owner owner) {
539	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
540	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
541	    }
542	
543	    /**
544	     * The number of owners that must already carry a registration date before a subsequent
545	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
546	     * once the count of owners already registered on that day <em>exceeds</em> this value.
547	     */
548	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
549	
550	    /**
551	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
552	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
553	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
554	     * existing owners before this one is persisted, so it reflects only the owners already
555	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
556	     *
557	     * @param owner the owner being created (with its {@code registrationDate} already set)
558	     */
559	    private void assignBulkSignupWarning(Owner owner) {
560	        LocalDate registrationDate = owner.getRegistrationDate();
561	        long count = this.clinicService.findAllOwners().stream()
562	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
563	            .count();
564	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
565	    }
566	
567	    /**
568	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
569	     *
570	     * @param value the string to hash
571	     * @return the 64-character lower-case hex digest
572	     */
573	    private static String sha256Hex(String value) {
574	        try {
575	            byte[] digest = MessageDigest.getInstance("SHA-256")
576	                .digest(value.getBytes(StandardCharsets.UTF_8));
577	            StringBuilder sb = new StringBuilder(digest.length * 2);
578	            for (byte b : digest) {
579	                sb.append(String.format("%02x", b));
580	            }
581	            return sb.toString();
582	        }
583	        catch (NoSuchAlgorithmException e) {
584	            throw new IllegalStateException("SHA-256 not available", e);
585	        }
586	    }
587	
588	    /**
589	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
590	     * owner. This single key consolidates what used to be three separate duplicate checks
591	     * (telephone, email and household): the key is
592	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
593	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
594	     * matches an existing owner's. Because the telephone is part of the key, two members of the
595	     * same household (same {@code householdId}) with different telephones have different identity
596	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
597	     * and email have already been normalized by {@link #normalizeTelephone} and
598	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
599	     * input formats collapse to the same value.
600	     *
601	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
602	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
603	     *                                    whole identity key
604	     */
605	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
606	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress(),
607	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
608	        boolean duplicate = this.clinicService.findAllOwners().stream()
609	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getAddress(),
610	                owner.getTelephone(), owner.getEmail()))
611	            .anyMatch(identityKey::equals);
612	        if (duplicate) {
613	            throw new DuplicateIdentityException(identityKey);
614	        }
615	    }
616	
617	    /**
618	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
619	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
620	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
621	     * absent), and the {@code householdId} is derived from the collapsed {@code lastName} and
622	     * {@code address} the same way {@link #assignHouseholdId} assigns it (see
623	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
624	     * their whole identities match, regardless of the exact input formats.
625	     *
626	     * @param lastName  the owner's last name
627	     * @param address   the owner's address
628	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
629	     * @param email     the owner's email, possibly {@code null}
630	     * @return the canonical identity key
631	     */
632	    private static String identityKeyFor(String lastName, String address, String telephone, String email) {
633	        String normalizedTelephone = toE164(telephone);
634	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
635	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
636	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, address);
637	    }
638	
639	    /**
640	     * The maximum number of owners permitted in a single city. A create is rejected once the
641	     * owner's city already contains this many owners.
642	     */
643	    private static final long CITY_CAPACITY = 50;
644	
645	    /**
646	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
647	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
648	     * before this owner is persisted.
649	     *
650	     * @param city the submitted city
651	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
652	     */
653	    private void rejectCityAtCapacity(String city) {
654	        long count = this.clinicService.findAllOwners().stream()
655	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
656	            .count();
657	        if (count >= CITY_CAPACITY) {
658	            throw new CityAtCapacityException(city);
659	        }
660	    }
661	
662	    /**
663	     * The maximum number of owners permitted to be created in a single day. A create is
664	     * rejected once this many owners already carry today's {@code registrationDate}.
665	     */
666	    private static final long DAILY_LIMIT = 100;
667	
668	    /**
669	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
670	     * business day as their {@code registrationDate}. The day counted against is this create's
671	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
672	     * so owners are counted per adjusted business day. The count is taken before this owner is
673	     * persisted.
674	     *
675	     * @param businessDay the effective, business-day-adjusted registration date of this create
676	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
677	     */
678	    private void rejectDailyLimit(LocalDate businessDay) {
679	        long count = this.clinicService.findAllOwners().stream()
680	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
681	            .count();
682	        if (count >= DAILY_LIMIT) {
683	            throw new DailyOwnerLimitExceededException(businessDay);
684	        }
685	    }
686	
687	    /**
688	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
689	     * every internal run of whitespace is collapsed to a single space, and the result is
690	     * lower-cased. A {@code null} value collapses to the empty string.
691	     *
692	     * @param value the value to canonicalize, possibly {@code null}
693	     * @return the collapsed, lower-cased value
694	     */
695	    private static String collapse(String value) {
696	        if (value == null) {
697	            return "";
698	        }
699	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
700	    }
701	
702	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
703	    @Override
704	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
705	        Owner owner = this.clinicService.findOwnerById(ownerId);
706	        if (owner != null) {
707	            Pet pet = owner.getPet(petId);
708	            if (pet != null) {
709	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
710	            }
711	        }
712	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
713	    }
714	}
