package org.springframework.samples.petclinic.rest.controller;

/**
 * Raised when a create or update request supplies an {@code email} that is present but
 * not a syntactically valid address. Carries the rejected value so the exception handler
 * can report a 400 Bad Request naming the {@code email} field.
 */
public class InvalidEmailException extends RuntimeException {

    private final String email;

    public InvalidEmailException(String email) {
        super("Invalid email address: " + email);
        this.email = email;
    }

    public String getEmail() {
        return this.email;
    }
}
