49	/**
50	 * Global Exception handler for REST controllers.
51	 * <p>
52	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
53	 *
54	 * @author Vitaliy Fedoriv
55	 * @author Alexander Dudkin
56	 */
57	@ControllerAdvice
58	public class ExceptionControllerAdvice {
59	
60	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
61	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
62	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
63	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
64	    private static final String ERROR_DUPLICATE_TELEPHONE = "An owner with the given telephone already exists";
65	    private static final String ERROR_DUPLICATE_EMAIL = "An owner with the given email already exists";
66	    private static final String ERROR_DUPLICATE_HOUSEHOLD = "An owner with the given last name and address already exists";
67	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the given identity already exists";
68	    private static final String ERROR_INVALID_EMAIL = "The request contains an invalid email address";
69	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
70	    private static final String ERROR_DAILY_LIMIT = "The maximum number of owners for today has already been reached";
71	
72	    /**
73	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
74	     * class.
75	     *
76	     * @param e     Object referring to the thrown exception.
77	     * @param status HTTP response status.
78	     * @param url URL request.
79	     */
80	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
81	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
82	        problemDetail.setType(URI.create(url.toString()));
83	        problemDetail.setTitle(e.getClass().getSimpleName());
84	        problemDetail.setDetail(detail);
85	        problemDetail.setProperty("timestamp", Instant.now());
86	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
87	        return problemDetail;
88	    }
89	
90	    /**
91	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
92	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
93	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
94	     * would catch it and report an authorization failure as a 500.
95	     *
96	     * @param e The {@link AccessDeniedException} to propagate
97	     * @throws AccessDeniedException always
98	     */
99	    @ExceptionHandler(AccessDeniedException.class)
100	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
101	        throw e;
102	    }
103	
104	    /**
105	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
106	     *
107	     * @param e The {@link Exception} to be handled
108	     * @param request {@link HttpServletRequest} object referring to the current request.
109	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
110	     */
111	    @ExceptionHandler(Exception.class)
112	    @ResponseBody
113	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
114	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
115	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
116	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
117	        return ResponseEntity.status(status).body(detail);
118	    }
119	
120	    /**
121	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
122	     * method returns a 404 Not Found status if an entity does not exist.
123	     *
124	     * @param e The {@link DataIntegrityViolationException} to be handled
125	     * @param request {@link HttpServletRequest} object referring to the current request.
126	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
127	     */
128	    @ExceptionHandler(DataIntegrityViolationException.class)
129	    @ResponseBody
130	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
131	        logger.warn("Data integrity violation at {} {}: {}",
132	            request.getMethod(),
133	            request.getRequestURI(),
134	            e.getMessage());
135	        logger.debug("Data integrity violation stacktrace", e);
136	        HttpStatus status = HttpStatus.NOT_FOUND;
137	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
138	        return ResponseEntity.status(status).body(detail);
139	    }
140	
141	    /**
142	     * Handles exception thrown by Bean Validation on controller methods parameters
143	     *
144	     * @param e The {@link MethodArgumentNotValidException} to be handled
145	     * @param request {@link HttpServletRequest} object referring to the current request.
146	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
147	     */
148	    @ExceptionHandler(MethodArgumentNotValidException.class)
149	    @ResponseBody
150	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
151	        HttpStatus status = HttpStatus.BAD_REQUEST;
152	        BindingErrorsResponse errors = new BindingErrorsResponse();
153	        BindingResult bindingResult = e.getBindingResult();
154	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
155	        List<String> invalidFields = bindingResult.getFieldErrors().stream()
156	            .map(FieldError::getField)
157	            .distinct()
158	            .toList();
159	        detail.setProperty("errors", invalidFields);
160	        if (bindingResult.hasErrors()) {
161	            errors.addAllErrors(bindingResult);
162	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
163	                .map(fieldError -> {
164	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
165	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
166	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
167	                        fieldError.getField(),
168	                        defaultMessage,
169	                        rejectedValue);
170	                    return new ValidationMessageDto(message)
171	                        .putAdditionalProperty("field", fieldError.getField())
172	                        .putAdditionalProperty("rejectedValue", rejectedValue)
173	                        .putAdditionalProperty("defaultMessage", defaultMessage);
174	                })
175	                .toList();
176	            logger.debug("Validation error at {} {}: {}",
177	                request.getMethod(),
178	                request.getRequestURI(),
179	                bindingResult.getFieldErrors());
180	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
181	            return ResponseEntity.status(status).body(detail);
182	        }
183	        return ResponseEntity.status(status).body(detail);
184	    }
