188	     * out mandatory fields. Returns a 400 Bad Request whose body carries an {@code errors}
189	     * array listing the name of each offending field.
190	     *
191	     * @param e The {@link RequiredFieldsMissingException} to be handled
192	     * @param request {@link HttpServletRequest} object referring to the current request.
193	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
194	     */
195	    @ExceptionHandler(RequiredFieldsMissingException.class)
196	    @ResponseBody
197	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
198	        HttpStatus status = HttpStatus.BAD_REQUEST;
199	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
200	        detail.setProperty("errors", e.getFields());
201	        logger.debug("Missing required fields at {} {}: {}",
202	            request.getMethod(),
203	            request.getRequestURI(),
204	            e.getFields());
205	        return ResponseEntity.status(status).body(detail);
206	    }
207	
208	    /**
209	     * Handles {@link DuplicateTelephoneException} raised when a create request supplies a
210	     * normalized telephone already used by another owner. Returns a 409 Conflict whose body
211	     * carries an {@code errors} array naming the {@code telephone} field.
212	     *
213	     * @param e The {@link DuplicateTelephoneException} to be handled
214	     * @param request {@link HttpServletRequest} object referring to the current request.
215	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
216	     */
217	    /**
218	     * Handles {@link InvalidEmailException} raised when a create or update request supplies an
219	     * {@code email} that is present but not a syntactically valid address. Returns a 400 Bad
220	     * Request whose body carries an {@code errors} array naming the {@code email} field.
221	     *
222	     * @param e The {@link InvalidEmailException} to be handled
223	     * @param request {@link HttpServletRequest} object referring to the current request.
224	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
225	     */
226	    @ExceptionHandler(InvalidEmailException.class)
227	    @ResponseBody
228	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
229	        HttpStatus status = HttpStatus.BAD_REQUEST;
230	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_EMAIL);
231	        detail.setProperty("errors", List.of("email"));
232	        logger.debug("Invalid email at {} {}: {}",
233	            request.getMethod(),
234	            request.getRequestURI(),
235	            e.getEmail());
236	        return ResponseEntity.status(status).body(detail);
237	    }
238	
239	    /**
240	     * Handles {@link DuplicateEmailException} raised when a create request supplies an
241	     * {@code email} whose lower-cased form is already used by another owner. Returns a 409
242	     * Conflict whose body carries an {@code errors} array naming the {@code email} field.
243	     *
244	     * @param e The {@link DuplicateEmailException} to be handled
245	     * @param request {@link HttpServletRequest} object referring to the current request.
246	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
247	     */
248	    @ExceptionHandler(DuplicateEmailException.class)
249	    @ResponseBody
250	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
251	        HttpStatus status = HttpStatus.CONFLICT;
252	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_EMAIL);
253	        detail.setProperty("errors", List.of("email"));
254	        logger.debug("Duplicate email at {} {}: {}",
255	            request.getMethod(),
256	            request.getRequestURI(),
257	            e.getEmail());
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles {@link DuplicateIdentityException} raised when a create request supplies an owner
263	     * whose whole derived {@code identityKey} already equals that of an existing owner. This one
264	     * key consolidates the former telephone, email and household duplicate checks. Returns a 409
265	     * Conflict whose body carries an {@code errors} array naming the {@code identityKey} field.
266	     *
267	     * @param e The {@link DuplicateIdentityException} to be handled
268	     * @param request {@link HttpServletRequest} object referring to the current request.
269	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
270	     */
271	    @ExceptionHandler(DuplicateIdentityException.class)
272	    @ResponseBody
273	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
274	        HttpStatus status = HttpStatus.CONFLICT;
275	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
276	        detail.setProperty("errors", List.of("identityKey"));
277	        logger.debug("Duplicate identity at {} {}: {}",
278	            request.getMethod(),
279	            request.getRequestURI(),
280	            e.getIdentityKey());
281	        return ResponseEntity.status(status).body(detail);
282	    }
283	
284	    @ExceptionHandler(DuplicateTelephoneException.class)
285	    @ResponseBody
286	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
287	        HttpStatus status = HttpStatus.CONFLICT;
288	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_TELEPHONE);
289	        detail.setProperty("errors", List.of("telephone"));
290	        logger.debug("Duplicate telephone at {} {}: {}",
291	            request.getMethod(),
292	            request.getRequestURI(),
293	            e.getTelephone());
294	        return ResponseEntity.status(status).body(detail);
295	    }
296	
297	    /**
298	     * Handles {@link DuplicateHouseholdException} raised when a create request supplies a
299	     * last name and address already used by another owner (compared case-insensitively with
300	     * collapsed whitespace) without opting in via {@code sharesHousehold}. Returns a 409
301	     * Conflict whose body carries an {@code errors} array naming the {@code lastName} and
302	     * {@code address} fields.
303	     *
304	     * @param e The {@link DuplicateHouseholdException} to be handled
305	     * @param request {@link HttpServletRequest} object referring to the current request.
306	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
307	     */
308	    @ExceptionHandler(DuplicateHouseholdException.class)
309	    @ResponseBody
310	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
311	        HttpStatus status = HttpStatus.CONFLICT;
312	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_HOUSEHOLD);
313	        detail.setProperty("errors", List.of("lastName", "address"));
314	        logger.debug("Duplicate household at {} {}: {} / {}",
315	            request.getMethod(),
316	            request.getRequestURI(),
317	            e.getLastName(),
318	            e.getAddress());
319	        return ResponseEntity.status(status).body(detail);
320	    }
321	
322	    /**
323	     * Handles {@link CityAtCapacityException} raised when a create request supplies a
324	     * {@code city} that already contains the maximum number of owners (compared
325	     * case-insensitively). Returns a 409 Conflict whose body carries an {@code errors}
326	     * array naming the {@code city} field.
327	     *
328	     * @param e The {@link CityAtCapacityException} to be handled
329	     * @param request {@link HttpServletRequest} object referring to the current request.
330	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
331	     */
332	    @ExceptionHandler(CityAtCapacityException.class)
333	    @ResponseBody
334	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
335	        HttpStatus status = HttpStatus.CONFLICT;
336	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
337	        detail.setProperty("errors", List.of("city"));
338	        logger.debug("City at capacity at {} {}: {}",
339	            request.getMethod(),
340	            request.getRequestURI(),
341	            e.getCity());
342	        return ResponseEntity.status(status).body(detail);
343	    }
344	
345	    /**
346	     * Handles {@link DailyOwnerLimitExceededException} raised when a create request arrives
347	     * after the maximum number of owners for the current day (counted by
348	     * {@code registrationDate}) has already been reached. Returns a 429 Too Many Requests.
349	     *
350	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
351	     * @param request {@link HttpServletRequest} object referring to the current request.
352	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
353	     */
354	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
355	    @ResponseBody
356	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
357	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
358	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT);
359	        detail.setProperty("errors", List.of("registrationDate"));
360	        logger.debug("Daily owner limit reached at {} {}: {}",
361	            request.getMethod(),
362	            request.getRequestURI(),
363	            e.getDate());
364	        return ResponseEntity.status(status).body(detail);
365	    }
366	
367	}
